import numpy as np
import pandas as pd

def pandas_ewma(r, lam, init_window=20):
    r = np.asarray(r, dtype=float)
    x = pd.Series(np.r_[r[:init_window].var(), r[:-1] ** 2])
    return x.ewm(alpha=1 - lam, adjust=False).mean().to_numpy()

def ewma_vs_pandas(r, lam):
    return float(np.max(np.abs(ewma_variance(r, lam) - pandas_ewma(r, lam))))
